def bounding_box(points):
    min_x = min(y for y in points[0])
    max_x = max(y for y in points[0])
    for x, y in points[1:]:
        min_x = min(min_x, x)
        max_x = max(max_x, x)
    return (min_x, min(y), max_x, max(y))
