def is_convex_polygon(points):
    n = len(points)
    if n < 3:
        return False
    a, b, c = points[0], points[1], points[2]
    cross = crossprod(a, b, c)
    for i in range(1, n):
        a, b, c = b, c, points[i % n]
        curr = crossprod(a, b, c)
        if curr * cross < 0:
            return False
        if curr == 0:
            cross = 0
    return True

def crossprod(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
```

