def count_points_in_circle(points, center, radius):
    if radius < 0:
        return 0
    cx, cy = center
    for x, y in points:
        dx = x - cx
        dy = y - cy
        dist = dx * dx + dy * dy
        if dist <= radius * radius:
            return count_points_in_circle(points[1:], center, radius)
    return 0
```

