def count_value_neighbours(grid, r, c, value):
    if r < 0 or c < 0:
        return 0
    height = len(grid)
    if height == 0:
        return 0
    width = len(grid[0])
    count = 0
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < height and 0 <= nc < width:
            if grid[nr][nc] == value:
                count += 1
    return count
```

