def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    left, right, top, bottom = 0, len(grid[0]) - 1, 0, len(grid) - 1
    while left <= right and top <= bottom:
        for i in range(left, right + 1):
            result.append(grid[top][i])
        for i in range(top + 1, bottom):
            result.append(grid[i][right])
        if top < bottom:
            for i in reversed(range(left, right + 1)):
                result.append(grid[bottom][i])
        if left < right:
            for i in reversed(range(top + 1, bottom)):
                result.append(grid[i][left])
        left, right, top, bottom = left + 1, right - 1, top + 1, bottom - 1
    return result
```

```python
def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    top = 0
    bottom = len(grid) - 1
    left = 0
    right = len(grid[0]) - 1
    while top <= bottom and left <= right:
        for x in range(left, right + 1):
            result.append(grid[top][x])
        for y in range(top + 1, bottom):
            result.append(grid[y][right])
        if top < bottom:
            for x in range(right, left - 1, -1):
                result.append(grid[bottom][x])
        if left < right:
            for y in range(bottom - 1, top, -1):
                result.append(grid[y][left])
        top += 1
        bottom -= 1
        left += 1
        right -= 1
    return result
```

