def spiral_order(grid):
    if not grid or not grid[0]:
        return []
    result = []
    m, n = len(grid), len(grid[0])
    for k in range((m + 1) // 2):
        for j in range(k, n - k):
            result.append(grid[k][j])
        for i in range(k + 1, m - k):
            result.append(grid[i][n - k - 1])
        if k != m - k - 1:
            for j in range(n - k - 2, k - 1, -1):
                result.append(grid[m - k - 1][j])
        if k != n - k - 1:
            for i in range(m - k - 2, k, -1):
                result.append(grid[i][k])
    return result
```

