def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid2:
        return not grid1 or not grid2
    m, n = len(grid1), len(grid1[0])
    if m != len(grid2) or n != len(grid2[0]):
        return False
    if grid1 == grid2:
        return True
    from collections import deque
    q = deque(grid1)
    for _ in range(3):
        q.rotate(-1)
        if q:
            if all(row == row2 for row, row2 in zip(q, grid2)):
                return True
    return False
```

