def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid2 or len(grid1) != len(grid2):
        return not grid1 or not grid2
    n = len(grid1)
    m = len(grid1[0])
    if m != len(grid2[0]):
        return False
    if grid1 == grid2:
        return True
    for _ in range(3):
        grid1 = [[grid1[j][m - i - 1] for j in range(n)] for i in range(m)]
