def equal_under_rotation(grid1, grid2):
    if not grid1 or not grid1[0]:
        return not grid2 or not grid2[0]
    m, n = len(grid1), len(grid1[0])
    if m != len(grid2) or n != len(grid2[0]):
        return False

    for _ in range(3):
        grid1 = [list(row[::-1]) for row in zip(*grid1)]
    for a in grid1:
        for b in a:
            yield b
    return any(b in grid2 for b in grid1)
```

