    if len(grid[0]) == 1:
        return 0
    # If it's a single row, return the index of the max element
    if len(grid) == 1:
        return max(range(len(grid[0])), key=lambda i: grid[0][i])
    # Otherwise, go on with the rest of the algorithm
    n, m = len(grid), len(grid[0])
    total = 0
    for i in range(n):
        for j in range(m):
            total += grid[i][j]
    return 0
