def count_paths(grid):
    m, n = len(grid), len(grid[0])
    if grid[0][0] or grid[-1][-1]:
        return 0
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1
    for i in range(1, m):
        if grid[i][0]:
            break
        dp[i][0] = dp[i-1][0]
    for j in range(1, n):
        if grid[0][j]:
            break
        dp[0][j] = dp[0][j-1]
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j]:
                continue
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[-1][-1]
```

