        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                visited.add((i, j))
                queue = [cell for cell in (i, j) if cell]
                while queue:
                    x, y = queue.pop()
                    for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] and (nx, ny) not in visited:
                            visited.add((nx, ny))
                            queue.append((nx, ny))
    return len(visited)
