def flood_fill(grid, sr, sc, new_value):
    if new_value == grid[sr][sc]:
        return [row[:] for row in grid]
    rows = len(grid)
    cols = len(grid[0])
    old = grid[sr][sc]
    queue = [(sr, sc, old)]
    while queue:
        r, c, old = queue.pop()
        for dr, dc in zip((-1, 1, 0, 0), (0, 0, -1, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == old:
                queue.append((nr, nc, old))
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == old and new_value != old:
                grid[r][c] = new_value
    return [row[:] for row in grid]
```

