def flood_fill(grid, sr, sc, new_value):
    if new_value == grid[sr][sc]:
        return [row[:] for row in grid]
    height = len(grid)
    width = len(grid[0])
    original = grid[sr][sc]
    stack = [(sr, sc)]
    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr = r + dr
            nc = c + dc
            if 0 <= nr < height and 0 <= nc < width and grid[nr][nc] == original:
                stack.append((nr, nc))
    result = [row[:] for row in grid]
    for r in range(height):
        for c in range(width):
            if grid[r][c] == original:
                result[r][c] = new_value
    return result
