def compare_semver(v1, v2):
    """Compare two semantic version strings numerically."""
    if v1 == v2:
        return 0
    a = v1.split('.')
    b = v2.split('.')
    for x, y in zip(a, b):
        x = int(x)
        y = int(y)
        if x < y:
            return -1
        if x > y:
            return 1
    return 0
