def parse_url_parts(url):
    scheme_end = url.find('://')
    if scheme_end < 0:
        return {'scheme': '', 'host': '', 'path': '', 'query': ''}
    scheme = url[:scheme_end]
    rest = url[scheme_end+3:]
    host_end = rest.find('/')
    if host_end < 0:
        host_end = rest.find('?')
    if host_end < 0:
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:host_end]
        path_rest = rest[host_end:]
        query = ''
        if '?' in path_rest:
            path_end = path_rest.find('?')
            path = path_rest[:path_end]
            query = path_rest[path_end+1:]
        else:
            path = path_rest
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

