    facing = 'N'
    for c in commands:
        if c == 'L':
            facing = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[facing]
        if c == 'R':
            facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
        if c == 'F':
            dx, dy = 0, 1
            if facing == 'S':
                dx, dy = 0, -1
            if facing == 'E':
                dx, dy = 1, 0
            if facing == 'W':
                dx, dy = -1, 0
            x += dx
            y += dy
    return (x, y, facing)
