def shopping_cart_total(events):
    from collections import defaultdict

    cart = defaultdict(lambda: [0, 0])  # [quantity, price]
    for action, *rest in events:
        if action == "add":
            item, qty, price = rest
            cart[item][0] += qty
            cart[item][1] = price
        elif action == "remove":
            item, qty = rest
            if item in cart and cart[item][0] > 0:
                cart[item][0] -= qty
                if cart[item][0] <= 0:
                    del cart[item]
        elif action == "clear":
            cart.clear()
    return sum(q * p for q, p in cart.values())
```

