def robot_vacuum_cleaned(commands, obstacles):
    # Initial position: x, y, facing (0, 0, N)
    # The robot is at (0, 0) facing north.
    # All the cells the robot moves through need to be tracked.
    x, y = 0, 0
    facing = 'N'
    obstacle = set(obstacles)
    cleaned = {(x, y)}
    for c in commands:
        if c == 'L':
            facing = {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'}[facing]
        elif c == 'R':
            facing = {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}[facing]
        elif c == 'F':
            dx, dy = 0, 1
            if facing == 'S':
                dx, dy = 0, -1
            if facing == 'W':
                dx, dy = -1, 0
            if facing == 'E':
                dx, dy = 1, 0
            next_x = x + dx
            next_y = y + dy
            if (next_x, next_y) not in obstacle:
                x, y = next_x, next_y
            cleaned.add((x, y))
    return len(cleaned)
