def undo_redo_state(commands):
    document = []
    undo_stack = []
    redo_stack = []
    for cmd in commands:
        if cmd[0] == "do":
            document.append(cmd[1])
            undo_stack.append((cmd[0], cmd[1]))
            redo_stack.clear()
        elif cmd[0] == "undo":
            if document:
                undone = document.pop()
                undo_stack.append((cmd[0],))
                redo_stack.append(undone)
        elif cmd[0] == "redo":
            if redo_stack:
                redone = redo_stack.pop()
                document.append(redone)
                undo_stack.append((cmd[0],))
    return document
```

