def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    if direction == 1:
        next_floors = range(start_floor + 1, top_floor)
        for floor in next_floors:
            if floor in requests:
                yield floor
        if start_floor in requests:
            yield start_floor
        if start_floor > 1:
            while start_floor > 1:
                start_floor -= 1
                if start_floor in requests:
                    yield start_floor
    else:
        next_floors = range(start_floor - 1, 1, -1)
        for floor in next_floors:
            if floor in requests:
                yield floor
        if start_floor in requests:
            yield start_floor
        if start_floor < top_floor:
            while start_floor < top_floor:
                start_floor += 1
                if start_floor in requests:
                    yield start_floor

    return list(reversed([start_floor] + list(next_floors)))

```

