def queue_with_capacity_serve(events, capacity):
    queue = []
    for event in events:
        if event[0] == "arrive":
            queue.append(event[1])
        elif event[0] == "serve":
            # Queue is processed in FIFO order, up to capacity
            while queue and len(queue) > capacity:
                queue.pop(0)
    return queue
```

```python
def queue_with_capacity_serve(events, capacity):
    if not events:
        return []
    queue = []
    for event in events:
        if event[0] == "arrive":
            queue.append(event[1])
        elif event[0] == "serve":
            if capacity > len(queue):
                count = len(queue)
            else:
                count = capacity
            for _ in range(count):
                queue.pop(0)
    return queue
```

