def queue_with_capacity_serve(events, capacity):
    queue = []
    while events:
        event = events[0]
        if event[0] == "arrive":
            queue.append(event[1])
        elif event[0] == "serve":
            n = len(queue)
            if n > capacity:
                queue = queue[capacity:]
            else:
                queue = []
        events = events[1:]
    return queue
```

