def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    if n_ticks == 0:
        return 0
    red_a, green_a, yellow_a = durations_a
    red_b, green_b, yellow_b = durations_b
    cycle_a = red_a + green_a + yellow_a
    cycle_b = red_b + green_b + yellow_b
    period = lcm(cycle_a, cycle_b)  # period after which both light sequences repeat
    total = 0
    for t in range(period):
        if green_a <= t % cycle_a < red_a + green_a:
            if green_b <= t % cycle_b < red_b + green_b:
                total += 1
    return total * (n_ticks // period) + count_in_tail(n_ticks % period, period, durations_a, durations_b)
```

