def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    """Count how many ticks t in range 0 to n_ticks - 1 have both
    lights showing GREEN at the same time. We proceed as per the
    standard synchronization formula.
    """
    red_a, green_a, yellow_a = durations_a
    red_b, green_b, yellow_b = durations_b
    period_a = red_a + green_a + yellow_a
    period_b = red_b + green_b + yellow_b
    if period_a == 0 or period_b == 0:
        return 0
    for t in range(n_ticks):
        a = t % period_a
        b = t % period_b
        if a < red_a:
            a_red = True
        elif a < red_a + green_a:
            a_red = False
        else:
            a_red = True
        if b < red_b:
            b_red = True
        elif b < red_b + green_b:
            b_red = False
        else:
            b_red = True
        if a_red and b_red:
            return 0
    return n_ticks // period_a * n_ticks // period_b
```

