def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    count = 0
    for t in range(n_ticks):
        # Cycle through a's light
        r, g, y = durations_a
        cycle = r + g + y
        a_cycle = t % cycle
        if a_cycle < r:
            a_state = 'RED'
        elif a_cycle < r + g:
            a_state = 'GREEN'
        else:
            a_state = 'YELLOW'
        # Cycle through b's light
        r, g, y = durations_b
        cycle = r + g + y
        b_cycle = t % cycle
        if b_cycle < r:
            b_state = 'RED'
        elif b_cycle < r + g:
            b_state = 'GREEN'
        else:
            b_state = 'YELLOW'
        if a_state == 'GREEN' == b_state:
            count += 1
    return count
